-- =============================================================================
-- V172 — OCCPL's pincode and zone master (Pincode_Master_NEW_DT_15-4-2024, shared by the user on 2026-11-25)
-- loaded once into the global pincode master. Generated, do not edit.
--
-- Per pincode: its direction zone (NORTH, SOUTH, EAST, WEST, CENTRAL) into `zone`, its pricing region into
-- `regional_zone_id`, and document / surface / air coverage into the V171 columns:
--   Doc:     serviceable = "Yes", ODA = the "Doc Is ODA" column, TAT = "Doc TAT" hours
--   Surface: serviceable unless "No Service", ODA when "ODA", TAT = "Surface TAT" hours
--   Air:     the same from "Air Service Y/N" and "Air TAT"
-- The pincode's own serviceable / COD / ODA flags are left as they are.
--
-- Regional zones created: Pune, X - Pune, Maharashtra, X - Maharashtra, Vidharbha, Rest of India, North East.
-- Skipped: 40 international rows and fake pincodes (0, 1, 2, 5, China, Singapore…); 421401 and 465691, listed
-- twice in the sheet, take their first row.
-- A pincode in the sheet but not in the master is added under a new area of the same city as the nearest pincode
-- on file with the same first three digits (same sorting district); one with no such neighbour is left out.
-- Safe to run on any database: regional zones are reused by code, and only pincodes on file are updated.
-- =============================================================================

SET @p = UNHEX('00000000000000000000000000000001');

SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, 'PUNE', 'Pune', 'From the OCCPL pincode master (V172)', 'ACTIVE', 0, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @p AND code = 'PUNE' AND deleted = FALSE);
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, 'X_PUNE', 'X - Pune', 'From the OCCPL pincode master (V172)', 'ACTIVE', 1, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @p AND code = 'X_PUNE' AND deleted = FALSE);
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, 'MAHARASHTRA', 'Maharashtra', 'From the OCCPL pincode master (V172)', 'ACTIVE', 2, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @p AND code = 'MAHARASHTRA' AND deleted = FALSE);
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, 'X_MAHARASHTRA', 'X - Maharashtra', 'From the OCCPL pincode master (V172)', 'ACTIVE', 3, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @p AND code = 'X_MAHARASHTRA' AND deleted = FALSE);
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, 'VIDHARBHA', 'Vidharbha', 'From the OCCPL pincode master (V172)', 'ACTIVE', 4, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @p AND code = 'VIDHARBHA' AND deleted = FALSE);
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, 'REST_OF_INDIA', 'Rest of India', 'From the OCCPL pincode master (V172)', 'ACTIVE', 5, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @p AND code = 'REST_OF_INDIA' AND deleted = FALSE);
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, 'NORTH_EAST', 'North East', 'From the OCCPL pincode master (V172)', 'ACTIVE', 6, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_regional_zones WHERE company_id = @p AND code = 'NORTH_EAST' AND deleted = FALSE);

DROP TABLE IF EXISTS tmp_pin_master;
CREATE TABLE tmp_pin_master (
    pincode CHAR(6) NOT NULL PRIMARY KEY, region VARCHAR(30) NOT NULL, zone VARCHAR(20) NOT NULL, city VARCHAR(150) NOT NULL,
    doc_s BOOLEAN NOT NULL, doc_oda BOOLEAN NOT NULL, doc_tat INT NULL,
    sur_s BOOLEAN NOT NULL, sur_oda BOOLEAN NOT NULL, sur_tat INT NULL,
    air_s BOOLEAN NOT NULL, air_oda BOOLEAN NOT NULL, air_tat INT NULL,
    regional_zone_id BINARY(16) NULL, neighbour_area_id BINARY(16) NULL, city_id BINARY(16) NULL, new_area_id BINARY(16) NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;


UPDATE tmp_pin_master t
JOIN master_regional_zones z ON z.company_id = @p AND z.code = t.region AND z.deleted = FALSE
SET t.regional_zone_id = z.id;

-- Pincodes on file: zone, regional zone and coverage.
UPDATE master_pincodes p
JOIN tmp_pin_master t ON t.pincode = p.code
SET p.zone = t.zone, p.regional_zone_id = t.regional_zone_id,
    p.doc_serviceable = t.doc_s, p.doc_oda = t.doc_oda, p.doc_tat_hours = t.doc_tat,
    p.surface_serviceable = t.sur_s, p.surface_oda = t.sur_oda, p.surface_tat_hours = t.sur_tat,
    p.air_serviceable = t.air_s, p.air_oda = t.air_oda, p.air_tat_hours = t.air_tat,
    p.updated_at = UTC_TIMESTAMP(6), p.version = p.version + 1
WHERE p.company_id = @p AND p.deleted = FALSE;

-- Pincodes not on file: borrow the city of the nearest pincode on file with the same first three digits.
UPDATE tmp_pin_master t
SET t.neighbour_area_id = (
    SELECT n.area_id FROM master_pincodes n
    WHERE n.company_id = @p AND n.deleted = FALSE AND LEFT(n.code, 3) = LEFT(t.pincode, 3)
    ORDER BY ABS(CAST(n.code AS SIGNED) - CAST(t.pincode AS SIGNED)), n.code LIMIT 1)
WHERE NOT EXISTS (SELECT 1 FROM master_pincodes p WHERE p.company_id = @p AND p.code = t.pincode);

UPDATE tmp_pin_master t JOIN master_areas a ON a.id = t.neighbour_area_id SET t.city_id = a.city_id;

-- One area per (city, name): reuse one already on file, else add it (several new pincodes can share one).
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, CONCAT('A', x.pincode, '_', UPPER(LEFT(MD5(CONCAT(x.pincode, '|', x.city)), 8))), x.city,
       'From the OCCPL pincode master (V172)', 'ACTIVE', 0, x.city_id, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM (SELECT t.city_id, t.city, MIN(t.pincode) pincode FROM tmp_pin_master t WHERE t.city_id IS NOT NULL GROUP BY t.city_id, t.city) x
WHERE NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.city_id = x.city_id AND a.name = x.city);

UPDATE tmp_pin_master t
JOIN master_areas a ON a.company_id = @p AND a.city_id = t.city_id AND a.name = t.city AND a.deleted = FALSE
SET t.new_area_id = a.id
WHERE t.city_id IS NOT NULL;

                             prepaid_available, pickup_available, zone, oda_applicable, regional_zone_id,
                             doc_serviceable, doc_oda, doc_tat_hours, surface_serviceable, surface_oda, surface_tat_hours,
                             air_serviceable, air_oda, air_tat_hours, created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, t.pincode, t.city, 'From the OCCPL pincode master (V172)', 'ACTIVE', 0, t.new_area_id,
       TRUE, TRUE, TRUE, TRUE, t.zone, FALSE, t.regional_zone_id,
       t.doc_s, t.doc_oda, t.doc_tat, t.sur_s, t.sur_oda, t.sur_tat, t.air_s, t.air_oda, t.air_tat,
       UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM tmp_pin_master t
WHERE t.new_area_id IS NOT NULL;

SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, p.id, t.new_area_id, TRUE, FALSE, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM tmp_pin_master t JOIN master_pincodes p ON p.company_id = @p AND p.code = t.pincode AND p.area_id = t.new_area_id
WHERE t.new_area_id IS NOT NULL;

DROP TABLE tmp_pin_master;
